SELECT fn_cp_import_case('conflits-differend-copropriete-assemblee', '{"slug": "conflits-differend-copropriete-assemblee", "title": "L''assemblée générale a dégénéré, le syndic a appelé", "theme_slug": "gestion-conflits", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 20 heures. Vous êtes appelée dans une salle commune où une assemblée générale de copropriété a dégénéré en désaccord vif entre plusieurs copropriétaires, le syndic ayant sollicité votre intervention face à cette agitation qui perturbe le déroulement normal de cette réunion formelle, sans qu''aucune infraction ne soit pour autant caractérisée dans ce cadre strictement privé de gestion collective. Cette configuration, où ce désaccord de gestion reste circonscrit au fonctionnement interne de cette copropriété, nécessite de faire cesser ce trouble sans entrer dans le débat de fond qui oppose ces copropriétaires sur la gestion de leur immeuble.\n\nCette situation, caractéristique des réunions formelles qui dégénèrent sous l''effet de tensions accumulées entre copropriétaires, impose de vous concentrer exclusivement sur le rétablissement du calme plutôt que sur une quelconque prise de position dans ce débat de gestion qui reste étranger à votre rôle.\n\nCette configuration nécessite de faire cesser ce trouble sans entrer dans ce débat de fond, cette distinction restant essentielle pour une intervention appropriée face à ce désaccord de gestion strictement privé.", "questions": [{"position": 1, "max_points": 5, "label": "Comment faites-vous cesser ce trouble sans entrer dans ce débat de fond sur la gestion de cette copropriété ?", "hint": "Cette distinction doit rester claire entre l''apaisement de cette agitation et toute prise de position sur ce débat de gestion qui reste étranger à votre compétence d''intervention.", "perfect": "Je fais cesser cette agitation en m''adressant fermement à l''ensemble des personnes présentes, cette action restant prioritaire indépendamment du fond de ce désaccord de gestion.\n\nJe reste factuelle sur la nécessité de rétablir un calme minimal pour permettre la poursuite ou la clôture normale de cette assemblée, sans me prononcer sur son contenu.\n\nJe reste attentive à ne jamais donner mon avis sur les questions de gestion débattues, cette neutralité restant essentielle face à ce cadre strictement privé de copropriété.\n\nJe reste attentive à identifier les personnes à l''origine de cette agitation, cette identification restant utile pour cibler mon intervention sans m''immiscer dans le débat lui-même.", "points": [{"position": 1, "label": "Faire cesser cette agitation en s''adressant fermement aux personnes présentes", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : action prioritaire indépendante du fond du désaccord.", "groups": [{"position": 1, "keywords": ["agitation cessée", "action prioritaire", "désaccord de gestion"]}]}, {"position": 2, "label": "Rester factuelle sur la nécessité de rétablir le calme sans se prononcer sur le contenu", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Calme rétabli sans avis sur le fond.", "groups": [{"position": 1, "keywords": ["calme rétabli", "contenu non commenté", "position neutre"]}]}, {"position": 3, "label": "Ne jamais donner son avis sur les questions de gestion débattues", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Neutralité face à ce cadre privé de copropriété.", "groups": [{"position": 1, "keywords": ["avis non donné", "neutralité maintenue", "cadre privé"]}]}, {"position": 4, "label": "Identifier les personnes à l''origine de cette agitation", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Identification ciblant l''intervention sans s''immiscer dans le débat.", "groups": [{"position": 1, "keywords": ["personnes identifiées", "intervention ciblée", "débat préservé"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment traitez-vous ce syndic et sa demande d''intervention face à cette situation ?", "hint": "Ce syndic reste à l''origine de cette sollicitation et mérite une écoute appropriée, cette gestion devant rester équilibrée avec l''ensemble des copropriétaires présents à cette réunion.", "perfect": "J''écoute la demande de ce syndic sur les raisons de son appel, cette écoute restant utile pour comprendre le contexte précis de cette dégradation de la réunion.\n\nJe reste factuelle avec lui sur les limites de mon intervention, cette clarification restant nécessaire pour qu''il comprenne que je ne me substitue pas à son rôle de gestion.\n\nJe reste attentive à ne pas le placer en position privilégiée par rapport aux autres copropriétaires présents, cette neutralité restant essentielle dans ce cadre collectif.\n\nJe reste disponible pour l''aider à rétablir les conditions d''une poursuite ou d''une clôture normale de cette assemblée générale.", "points": [{"position": 1, "label": "Écouter la demande du syndic sur les raisons de son appel", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : compréhension du contexte de la dégradation.", "groups": [{"position": 1, "keywords": ["demande écoutée", "contexte compris", "dégradation expliquée"]}]}, {"position": 2, "label": "Rester factuelle sur les limites de son intervention", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Clarification du rôle distinct de la gestion.", "groups": [{"position": 1, "keywords": ["limites précisées", "rôle clarifié", "gestion distincte"]}]}, {"position": 3, "label": "Ne pas placer ce syndic en position privilégiée par rapport aux autres", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Neutralité dans ce cadre collectif.", "groups": [{"position": 1, "keywords": ["neutralité maintenue", "position équilibrée", "cadre collectif"]}]}, {"position": 4, "label": "Rester disponible pour aider à rétablir une poursuite normale de cette assemblée", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Disponibilité facilitant la clôture normale.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "assemblée facilitée", "clôture normale"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment concluez-vous cette intervention face à ce désaccord qui pourrait perdurer après votre départ ?", "hint": "Cette conclusion doit tenir compte du risque de reprise de ce désaccord après votre départ, cette réalité méritant une anticipation appropriée avant de quitter cette réunion.", "perfect": "Je m''assure que le calme minimal est rétabli avant de quitter cette salle, cette vérification restant nécessaire pour éviter une reprise immédiate de cette agitation.\n\nJe reste factuelle sur les modalités habituelles de résolution des désaccords en assemblée générale, cette information pouvant être utile à ces copropriétaires pour l''avenir.\n\nJe reste attentive à ne pas quitter les lieux si la tension reste trop vive, cette prudence restant appropriée pour éviter une reprise immédiate de cet incident.\n\nJe reste disponible pour une nouvelle intervention si cette agitation devait reprendre, cette disponibilité restant appropriée compte tenu de la nature parfois récurrente de ce type de désaccord.", "points": [{"position": 1, "label": "S''assurer que le calme minimal est rétabli avant de quitter la salle", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : vérification évitant une reprise immédiate.", "groups": [{"position": 1, "keywords": ["calme vérifié", "reprise évitée", "salle quittée"]}]}, {"position": 2, "label": "Rester factuelle sur les modalités habituelles de résolution en assemblée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Information utile pour l''avenir des copropriétaires.", "groups": [{"position": 1, "keywords": ["modalités expliquées", "résolution habituelle", "avenir informé"]}]}, {"position": 3, "label": "Ne pas quitter les lieux si la tension reste trop vive", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Prudence évitant une reprise immédiate.", "groups": [{"position": 1, "keywords": ["tension évaluée", "départ différé", "prudence appliquée"]}]}, {"position": 4, "label": "Rester disponible pour une nouvelle intervention en cas de reprise", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Disponibilité compte tenu de la récurrence possible.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "reprise possible", "nouvelle intervention"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('conflits-personne-hostile-refuse-soins-pompiers', '{"slug": "conflits-personne-hostile-refuse-soins-pompiers", "title": "Il repousse les pompiers venus pour lui", "theme_slug": "gestion-conflits", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 2 heures. Sur la voie publique, un homme repousse physiquement les pompiers venus pour le secourir suite à un appel de riverains, cette hostilité envers ces secours partenaires nécessitant votre intervention pour sécuriser leur action tout en tentant de rétablir un dialogue avec cet homme qui refuse cette prise en charge médicale dont il semble pourtant avoir besoin. Cette configuration, où cette hostilité se dirige spécifiquement contre un service partenaire venu porter assistance, impose de concilier la protection physique de ces pompiers avec la recherche d''un dialogue permettant d''obtenir l''adhésion de cet homme aux soins qui lui sont proposés.\n\nCette situation, caractéristique des interventions conjointes où l''agressivité d''une personne envers les services de secours complique leur mission de soin, nécessite une action qui sécurise d''abord ces professionnels avant de chercher à convaincre cette personne d''accepter cette prise en charge nécessaire.\n\nCette configuration nécessite de sécuriser ces pompiers et de rétablir le dialogue avec cet homme, cette double exigence restant essentielle face à cette hostilité dirigée contre ce service partenaire venu l''assister.", "questions": [{"position": 1, "max_points": 5, "label": "Comment sécurisez-vous ces pompiers face à cette hostilité de cet homme envers eux ?", "hint": "Cette sécurisation doit rester la priorité immédiate, cette protection restant essentielle pour permettre à ces pompiers de poursuivre leur mission de soin en toute sécurité.", "perfect": "Je me positionne entre cet homme et ces pompiers pour assurer leur sécurité, cette interposition restant nécessaire face à cette hostilité manifeste à leur égard.\n\nJe reste attentive à contenir les mouvements de cet homme pour éviter tout contact physique supplémentaire avec ces pompiers déjà repoussés.\n\nJe communique avec ces pompiers sur la conduite à tenir, cette coordination restant essentielle pour permettre la reprise de leur intervention en toute sécurité.\n\nJe reste attentive à évaluer si un renfort supplémentaire s''avère nécessaire pour sécuriser durablement cette intervention conjointe.", "points": [{"position": 1, "label": "Se positionner entre cet homme et ces pompiers pour assurer leur sécurité", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : interposition face à cette hostilité manifeste.", "groups": [{"position": 1, "keywords": ["interposition réalisée", "pompiers protégés", "hostilité manifeste"]}]}, {"position": 2, "label": "Contenir les mouvements de cet homme pour éviter un contact supplémentaire", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Prévention d''un nouveau contact avec les pompiers.", "groups": [{"position": 1, "keywords": ["mouvements contenus", "contact évité", "pompiers repoussés"]}]}, {"position": 3, "label": "Communiquer avec ces pompiers sur la conduite à tenir", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Coordination permettant la reprise de leur intervention.", "groups": [{"position": 1, "keywords": ["coordination assurée", "intervention reprise", "conduite tenue"]}]}, {"position": 4, "label": "Évaluer si un renfort supplémentaire s''avère nécessaire", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Sécurisation durable de cette intervention conjointe.", "groups": [{"position": 1, "keywords": ["renfort évalué", "sécurisation durable", "intervention conjointe"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment rétablissez-vous le dialogue avec cet homme pour obtenir son adhésion aux soins proposés ?", "hint": "Ce dialogue doit être recherché activement une fois cette sécurisation assurée, cette adhésion aux soins restant préférable à toute contrainte pour cet homme qui semble en avoir besoin.", "perfect": "Je m''adresse calmement à cet homme une fois cette sécurisation assurée, cette approche restant préférable pour tenter de comprendre son refus de cette prise en charge.\n\nJe reste attentive aux raisons de son hostilité envers ces pompiers, cette compréhension pouvant m''aider à adapter mon discours pour faciliter ce dialogue.\n\nJe reste factuelle sur la nécessité des soins qui lui sont proposés, cette information restant utile pour l''inciter à accepter cette prise en charge de son plein gré.\n\nJe reste patiente face à ses réticences initiales, cette patience restant appropriée pour privilégier une adhésion plutôt qu''une contrainte à ces soins nécessaires.", "points": [{"position": 1, "label": "S''adresser calmement à cet homme une fois la sécurisation assurée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : approche préférable pour comprendre son refus.", "groups": [{"position": 1, "keywords": ["approche calme", "sécurisation assurée", "refus compris"]}]}, {"position": 2, "label": "Rester attentive aux raisons de son hostilité envers ces pompiers", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Compréhension adaptant le discours.", "groups": [{"position": 1, "keywords": ["raisons comprises", "discours adapté", "hostilité expliquée"]}]}, {"position": 3, "label": "Rester factuelle sur la nécessité des soins proposés", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Information incitant à une adhésion volontaire.", "groups": [{"position": 1, "keywords": ["soins expliqués", "adhésion volontaire", "nécessité précisée"]}]}, {"position": 4, "label": "Rester patiente face à ses réticences initiales", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Patience privilégiant l''adhésion à la contrainte.", "groups": [{"position": 1, "keywords": ["patience maintenue", "adhésion privilégiée", "contrainte évitée"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment rendez-vous compte de cette situation pour permettre une prise en charge appropriée de cet homme ?", "hint": "Ce compte rendu doit permettre d''orienter la suite de cette prise en charge, cette transmission restant nécessaire compte tenu de la complexité de cette situation impliquant ces services partenaires.", "perfect": "Je transmets à ma hiérarchie et aux pompiers les éléments recueillis sur cette hostilité et ses éventuelles causes, cette information restant utile pour cette prise en charge.\n\nJe reste factuelle sur le déroulement de cette intervention conjointe, cette rigueur restant nécessaire pour un compte rendu fidèle de cette situation complexe.\n\nJe reste attentive à signaler si cet homme présente des signes qui pourraient orienter vers une prise en charge psychiatrique adaptée à son état.\n\nJe reste disponible pour accompagner cette prise en charge jusqu''à son terme, cette disponibilité restant appropriée compte tenu de la sensibilité de cette situation.", "points": [{"position": 1, "label": "Transmettre les éléments recueillis sur cette hostilité et ses causes", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : information utile pour cette prise en charge.", "groups": [{"position": 1, "keywords": ["éléments transmis", "hostilité expliquée", "prise en charge orientée"]}]}, {"position": 2, "label": "Rester factuelle sur le déroulement de cette intervention conjointe", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Rigueur pour un compte rendu fidèle.", "groups": [{"position": 1, "keywords": ["déroulement rapporté", "compte rendu fidèle", "intervention conjointe"]}]}, {"position": 3, "label": "Signaler les signes pouvant orienter vers une prise en charge psychiatrique", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Orientation adaptée à son état.", "groups": [{"position": 1, "keywords": ["signes signalés", "prise en charge psychiatrique", "état évalué"]}]}, {"position": 4, "label": "Rester disponible pour accompagner cette prise en charge jusqu''au terme", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Disponibilité compte tenu de la sensibilité.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "prise en charge accompagnée", "sensibilité reconnue"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('conflits-riverains-exigent-une-action-immediate', '{"slug": "conflits-riverains-exigent-une-action-immediate", "title": "Une dizaine d''habitants vous entoure et exige des interpellations", "theme_slug": "gestion-conflits", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 19 heures. Dans un quartier, une dizaine d''habitants vous entoure et exige des interpellations immédiates concernant des nuisances qu''ils subissent régulièrement, cette pression collective exprimant des attentes qui dépassent manifestement le cadre légal dans lequel votre action doit nécessairement s''inscrire. Cette configuration, où cette demande pressante de ces riverains ne correspond pas aux possibilités réelles d''action immédiate dont vous disposez face à cette situation, nécessite d''expliquer les limites de votre action sans pour autant vous laisser dicter cette action par cette pression citoyenne collective.\n\nCette situation, caractéristique des attentes parfois excessives que les riverains peuvent formuler face à des nuisances répétées qui les affectent réellement dans leur quotidien, impose une pédagogie sur le cadre légal de votre action tout en reconnaissant la légitimité de leur exaspération face à cette situation persistante.\n\nCette configuration nécessite d''expliquer les limites de votre action sans vous laisser dicter cette action par cette pression collective, cette fermeté restant essentielle face à ces attentes qui dépassent le cadre légal de votre intervention.", "questions": [{"position": 1, "max_points": 5, "label": "Comment expliquez-vous les limites de votre action sans vous laisser dicter cette action par cette pression collective ?", "hint": "Cette explication doit rester claire et ferme, cette fermeté restant essentielle face à cette pression collective qui exige une action dépassant le cadre légal de votre intervention.", "perfect": "J''explique clairement à ces riverains le cadre légal qui encadre mon action, cette pédagogie restant nécessaire pour qu''ils comprennent les limites réelles de mon intervention.\n\nJe reste factuelle sur les conditions nécessaires à une interpellation, précisant que cette mesure ne peut être décidée sous la seule pression d''une demande collective.\n\nJe reste attentive à ne pas céder à cette pression collective, cette fermeté restant essentielle pour préserver le cadre légal qui doit gouverner toute décision de cette nature.\n\nJe reste factuelle sur les démarches appropriées que ces riverains pourraient entreprendre pour faire valoir leurs droits face à ces nuisances constatées.", "points": [{"position": 1, "label": "Expliquer clairement le cadre légal qui encadre son action", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : pédagogie sur les limites réelles.", "groups": [{"position": 1, "keywords": ["cadre légal expliqué", "limites comprises", "pédagogie appliquée"]}]}, {"position": 2, "label": "Rester factuelle sur les conditions nécessaires à une interpellation", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Mesure non décidée sous la seule pression collective.", "groups": [{"position": 1, "keywords": ["conditions précisées", "interpellation expliquée", "pression collective"]}]}, {"position": 3, "label": "Ne pas céder à cette pression collective", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Fermeté préservant le cadre légal.", "groups": [{"position": 1, "keywords": ["pression résistée", "fermeté maintenue", "cadre légal préservé"]}]}, {"position": 4, "label": "Informer des démarches appropriées pour faire valoir leurs droits", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Démarches face aux nuisances constatées.", "groups": [{"position": 1, "keywords": ["démarches informées", "droits évoqués", "nuisances constatées"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment reconnaissez-vous la légitimité de l''exaspération de ces riverains face à ces nuisances persistantes ?", "hint": "Cette exaspération reste légitime compte tenu de ces nuisances répétées qu''ils subissent réellement, cette reconnaissance restant compatible avec la fermeté nécessaire sur le cadre légal de votre action.", "perfect": "J''écoute attentivement l''exaspération de ces riverains, cette écoute restant nécessaire pour reconnaître la réalité des nuisances qu''ils subissent au quotidien.\n\nJe reste factuelle sur les démarches déjà entreprises ou envisageables pour traiter ces nuisances, cette information leur montrant que leur situation n''est pas ignorée.\n\nJe reste attentive à ne pas minimiser leur vécu quotidien face à ces nuisances, cette reconnaissance restant importante pour ne pas ajouter à leur frustration actuelle.\n\nJe reste disponible pour un suivi de cette situation, cette disponibilité restant rassurante pour ces riverains fatigués par ces nuisances persistantes.", "points": [{"position": 1, "label": "Écouter attentivement l''exaspération de ces riverains", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : reconnaissance de la réalité des nuisances.", "groups": [{"position": 1, "keywords": ["exaspération écoutée", "nuisances reconnues", "réalité admise"]}]}, {"position": 2, "label": "Rester factuelle sur les démarches déjà entreprises ou envisageables", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Information montrant que la situation n''est pas ignorée.", "groups": [{"position": 1, "keywords": ["démarches expliquées", "situation prise en compte", "information factuelle"]}]}, {"position": 3, "label": "Ne pas minimiser leur vécu quotidien face à ces nuisances", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Reconnaissance évitant d''ajouter à la frustration.", "groups": [{"position": 1, "keywords": ["vécu reconnu", "frustration non ajoutée", "minimisation évitée"]}]}, {"position": 4, "label": "Rester disponible pour un suivi de cette situation", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Disponibilité rassurante pour ces riverains fatigués.", "groups": [{"position": 1, "keywords": ["suivi proposé", "disponibilité maintenue", "riverains rassurés"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment gérez-vous cette pression physique de ce groupe qui vous entoure durant cet échange ?", "hint": "Cette proximité physique d''une dizaine de personnes mérite une attention particulière sur le plan de votre propre sécurité, cette vigilance restant nécessaire durant cet échange tendu.", "perfect": "Je reste attentive à cette proximité physique de ce groupe qui m''entoure, cette vigilance restant nécessaire pour ma propre sécurité durant cet échange tendu.\n\nJe reste attentive à maintenir un espace suffisant autour de moi, cette gestion de l''espace restant utile pour éviter tout sentiment d''oppression durant cette interaction.\n\nJe reste calme et posée face à cette pression collective, cette maîtrise restant essentielle pour ne pas transformer cette pression en confrontation plus vive.\n\nJe reste attentive à l''évolution de ce groupe durant cet échange, cette observation continue restant nécessaire pour détecter toute escalade possible de cette situation.", "points": [{"position": 1, "label": "Rester attentive à cette proximité physique pour sa propre sécurité", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : vigilance nécessaire durant cet échange tendu.", "groups": [{"position": 1, "keywords": ["proximité surveillée", "sécurité personnelle", "échange tendu"]}]}, {"position": 2, "label": "Maintenir un espace suffisant autour de soi", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Gestion de l''espace évitant un sentiment d''oppression.", "groups": [{"position": 1, "keywords": ["espace maintenu", "oppression évitée", "gestion spatiale"]}]}, {"position": 3, "label": "Rester calme et posée face à cette pression collective", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Maîtrise évitant une confrontation plus vive.", "groups": [{"position": 1, "keywords": ["calme maintenu", "confrontation évitée", "pression gérée"]}]}, {"position": 4, "label": "Rester attentive à l''évolution de ce groupe durant l''échange", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Observation détectant toute escalade possible.", "groups": [{"position": 1, "keywords": ["groupe observé", "escalade détectée", "situation surveillée"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('conflits-differend-entre-un-usager-et-un-agent-municipal', '{"slug": "conflits-differend-entre-un-usager-et-un-agent-municipal", "title": "Le placier et le commerçant s''invectivent devant les clients", "theme_slug": "gestion-conflits", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 10 heures. Sur un marché, le placier chargé de l''organisation des emplacements et un commerçant s''invectivent vivement devant de nombreux clients présents, ce conflit opposant un agent public dans l''exercice de ses fonctions à un administré autour d''un désaccord sur l''attribution d''un emplacement précis. Cette configuration, où l''une des parties à ce conflit reste elle-même un agent public exerçant une mission officielle, nécessite de rester parfaitement neutre malgré cette qualité particulière du placier qui pourrait naturellement inciter à une solidarité institutionnelle déplacée dans ce contexte.\n\nCette situation, caractéristique des tensions qui peuvent survenir entre un agent chargé d''une mission de service public et un usager qui conteste ses décisions, impose de traiter ce conflit avec la même impartialité que face à tout autre différend entre deux administrés ordinaires.\n\nCette configuration nécessite de rester neutre malgré la qualité d''agent public de l''une des parties, cette impartialité restant essentielle pour une intervention appropriée et crédible face à ce conflit.", "questions": [{"position": 1, "max_points": 5, "label": "Comment restez-vous neutre malgré la qualité d''agent public de l''une des parties à ce conflit ?", "hint": "Cette neutralité doit rester totale malgré cette qualité particulière du placier, cette impartialité restant essentielle pour ne pas privilégier indûment cet agent public dans votre appréciation de la situation.", "perfect": "Je traite ce placier et ce commerçant avec la même considération, cette égalité de traitement restant essentielle malgré la qualité d''agent public de l''un d''eux.\n\nJe reste attentive à ne pas accorder de crédit automatique à la version du placier du seul fait de sa qualité d''agent public, cette vigilance restant nécessaire pour une appréciation objective.\n\nJe recueille la version de chacune de ces deux parties avec la même attention, cette méthode restant appropriée pour éviter tout biais dans le traitement de ce conflit.\n\nJe reste consciente que cette impartialité conditionne la crédibilité de mon intervention aux yeux de l''ensemble des personnes présentes sur ce marché.", "points": [{"position": 1, "label": "Traiter ce placier et ce commerçant avec la même considération", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : égalité de traitement malgré la qualité d''agent public.", "groups": [{"position": 1, "keywords": ["considération égale", "traitement équitable", "agent public"]}]}, {"position": 2, "label": "Ne pas accorder de crédit automatique à la version du placier", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Vigilance pour une appréciation objective.", "groups": [{"position": 1, "keywords": ["crédit non automatique", "appréciation objective", "vigilance maintenue"]}]}, {"position": 3, "label": "Recueillir la version de chacune de ces deux parties avec la même attention", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Méthode évitant tout biais.", "groups": [{"position": 1, "keywords": ["versions recueillies", "biais évité", "attention égale"]}]}, {"position": 4, "label": "Rester consciente que cette impartialité conditionne sa crédibilité", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Crédibilité aux yeux des personnes présentes.", "groups": [{"position": 1, "keywords": ["crédibilité conditionnée", "impartialité essentielle", "personnes présentes"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment faites-vous cesser cette invective mutuelle devant ce public de clients présents ?", "hint": "Cette invective mutuelle doit cesser rapidement compte tenu de ce public nombreux, cette action restant prioritaire avant tout examen approfondi du fond de ce désaccord sur cet emplacement.", "perfect": "Je m''interpose fermement entre ces deux personnes pour mettre fin à cette invective mutuelle, cette action immédiate restant prioritaire face à ce public de clients présents.\n\nJe reste factuelle et ferme dans mes demandes envers ces deux parties, cette fermeté restant appropriée pour rétablir rapidement le calme sur ce marché fréquenté.\n\nJe reste attentive à séparer physiquement ces deux personnes si nécessaire, cette séparation restant utile pour éviter toute reprise immédiate de cet échange verbal vif.\n\nJe reste consciente de l''importance de résoudre rapidement cet incident pour permettre la reprise normale de l''activité commerciale sur ce marché.", "points": [{"position": 1, "label": "S''interposer fermement pour mettre fin à cette invective mutuelle", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : action immédiate face à ce public présent.", "groups": [{"position": 1, "keywords": ["interposition réalisée", "invective stoppée", "public présent"]}]}, {"position": 2, "label": "Rester factuelle et ferme dans ses demandes envers ces deux parties", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Fermeté rétablissant rapidement le calme.", "groups": [{"position": 1, "keywords": ["demandes fermes", "calme rétabli", "marché fréquenté"]}]}, {"position": 3, "label": "Séparer physiquement ces deux personnes si nécessaire", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Séparation évitant une reprise de l''échange.", "groups": [{"position": 1, "keywords": ["personnes séparées", "reprise évitée", "échange vif"]}]}, {"position": 4, "label": "Reconnaître l''importance de résoudre rapidement cet incident", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Reprise normale de l''activité commerciale.", "groups": [{"position": 1, "keywords": ["résolution rapide", "activité reprise", "marché normalisé"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment traitez-vous le fond de ce désaccord sur l''attribution de cet emplacement une fois le calme rétabli ?", "hint": "Ce fond du désaccord relève de la compétence administrative de la gestion de ce marché plutôt que de votre propre compétence, cette distinction restant importante pour orienter correctement la suite.", "perfect": "Je reste attentive à distinguer clairement le trouble à l''ordre public que j''ai géré du fond de ce désaccord sur l''attribution de cet emplacement, qui relève d''une autre compétence.\n\nJe reste factuelle sur le fait que cette question d''attribution relève de la gestion administrative de ce marché plutôt que de mon appréciation personnelle.\n\nJe reste attentive à ne pas trancher moi-même cette question d''attribution, cette réserve restant essentielle compte tenu de la nature administrative de ce désaccord.\n\nJe reste attentive à orienter ces deux parties vers l''autorité compétente pour trancher définitivement cette question d''attribution d''emplacement sur ce marché.", "points": [{"position": 1, "label": "Distinguer le trouble géré du fond du désaccord d''attribution", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : distinction entre trouble et compétence administrative.", "groups": [{"position": 1, "keywords": ["trouble distingué", "fond du désaccord", "compétence différente"]}]}, {"position": 2, "label": "Rester factuelle sur la nature administrative de cette question", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Gestion administrative plutôt qu''appréciation personnelle.", "groups": [{"position": 1, "keywords": ["nature administrative", "gestion du marché", "appréciation personnelle évitée"]}]}, {"position": 3, "label": "Ne pas trancher soi-même cette question d''attribution", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Réserve compte tenu de la nature administrative.", "groups": [{"position": 1, "keywords": ["question non tranchée", "réserve maintenue", "désaccord administratif"]}]}, {"position": 4, "label": "Orienter vers l''autorité compétente pour trancher cette attribution", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Orientation vers l''autorité appropriée.", "groups": [{"position": 1, "keywords": ["autorité compétente", "attribution tranchée", "orientation donnée"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('conflits-personne-souhaite-retirer-sa-plainte-sous-pression', '{"slug": "conflits-personne-souhaite-retirer-sa-plainte-sous-pression", "title": "Elle est accompagnée de deux personnes qui répondent pour elle", "theme_slug": "gestion-conflits", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 17 heures. Au commissariat, une femme se présente accompagnée de deux personnes pour retirer une plainte qu''elle avait déposée précédemment, ces deux accompagnants répondant systématiquement à sa place lorsque vous lui posez des questions directes, cette configuration suggérant fortement que ce retrait pourrait être contraint plutôt que librement consenti par cette femme elle-même. Cette situation, où cette pression exercée par ces accompagnants insistants s''exerce directement au guichet de ce commissariat, nécessite d''isoler cette femme de ces deux personnes pour recueillir sa volonté réelle sans cette influence directe qui pourrait fausser cette expression.\n\nCette configuration, caractéristique des situations où un retrait de plainte pourrait masquer une pression exercée sur la victime plutôt qu''un choix véritablement libre et éclairé de sa part, impose une vigilance particulière avant d''acter tout retrait qui pourrait résulter de cette contrainte.\n\nCette situation nécessite d''isoler cette femme pour recueillir sa volonté réelle loin de cette pression, cette action restant essentielle pour s''assurer du caractère véritablement libre de ce retrait avant toute décision définitive.", "questions": [{"position": 1, "max_points": 5, "label": "Comment isolez-vous cette femme de ces deux accompagnants pour recueillir sa volonté réelle ?", "hint": "Cette isolation doit rester tactique et non brutale, cette séparation restant nécessaire pour permettre à cette femme de s''exprimer librement loin de cette pression exercée par ces accompagnants.", "perfect": "Je propose de manière naturelle un entretien individuel avec cette femme, cette démarche restant habituelle et ne devant pas éveiller de suspicion chez ces accompagnants présents.\n\nJe reste attentive à trouver un motif approprié pour séparer temporairement cette femme de ces deux personnes, cette tactique restant nécessaire pour recueillir sa parole libre.\n\nJe reste factuelle et rassurante une fois cette femme isolée, cette approche restant appropriée pour créer un climat de confiance propice à une expression sincère.\n\nJe reste attentive à ne pas brusquer cette séparation, cette prudence restant importante pour ne pas alerter ces accompagnants sur mes intentions réelles.", "points": [{"position": 1, "label": "Proposer un entretien individuel de manière naturelle", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : démarche habituelle ne devant pas éveiller de suspicion.", "groups": [{"position": 1, "keywords": ["entretien proposé", "démarche naturelle", "suspicion évitée"]}]}, {"position": 2, "label": "Trouver un motif approprié pour séparer temporairement ces personnes", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Tactique nécessaire pour recueillir la parole libre.", "groups": [{"position": 1, "keywords": ["motif trouvé", "séparation temporaire", "parole libre"]}]}, {"position": 3, "label": "Rester factuelle et rassurante une fois cette femme isolée", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Climat de confiance propice à une expression sincère.", "groups": [{"position": 1, "keywords": ["climat de confiance", "expression sincère", "approche rassurante"]}]}, {"position": 4, "label": "Ne pas brusquer cette séparation pour ne pas alerter les accompagnants", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Prudence évitant d''alerter sur les intentions réelles.", "groups": [{"position": 1, "keywords": ["séparation prudente", "accompagnants non alertés", "intentions préservées"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment recueillez-vous sa volonté réelle une fois cette femme isolée de ces accompagnants ?", "hint": "Cette volonté réelle doit être recueillie avec délicatesse, cette femme pouvant se trouver dans une situation de grande vulnérabilité face à cette pression qu''elle subit peut-être depuis un certain temps.", "perfect": "Je l''interroge avec délicatesse sur les raisons réelles de ce retrait de plainte, cette approche restant nécessaire pour distinguer un choix libre d''une décision contrainte.\n\nJe reste attentive aux signes de contrainte ou de peur qui pourraient transparaître dans son discours ou son comportement durant cet entretien individuel.\n\nJe l''informe clairement qu''elle peut s''exprimer librement dans ce cadre confidentiel, cette information restant essentielle pour la rassurer sur la sécurité de cet échange.\n\nJe reste attentive à ne pas la brusquer si elle reste réticente à se confier, cette patience restant appropriée compte tenu de la vulnérabilité potentielle de sa situation.", "points": [{"position": 1, "label": "Interroger avec délicatesse sur les raisons réelles de ce retrait", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : distinction entre choix libre et décision contrainte.", "groups": [{"position": 1, "keywords": ["raisons interrogées", "choix distingué", "décision contrainte"]}]}, {"position": 2, "label": "Rester attentive aux signes de contrainte ou de peur", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Signes transparaissant dans le discours ou comportement.", "groups": [{"position": 1, "keywords": ["signes observés", "contrainte détectée", "peur perçue"]}]}, {"position": 3, "label": "Informer clairement qu''elle peut s''exprimer librement dans ce cadre confidentiel", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Information rassurant sur la sécurité de l''échange.", "groups": [{"position": 1, "keywords": ["expression libre", "cadre confidentiel", "sécurité assurée"]}]}, {"position": 4, "label": "Ne pas la brusquer si elle reste réticente à se confier", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Patience compte tenu de sa vulnérabilité potentielle.", "groups": [{"position": 1, "keywords": ["patience maintenue", "réticence respectée", "vulnérabilité reconnue"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment décidez-vous de la suite à donner à cette demande de retrait selon ce que vous aurez recueilli ?", "hint": "Cette décision doit reposer sur ce que vous aurez pu établir durant cet entretien individuel, cette suite devant rester adaptée au caractère libre ou contraint de ce retrait exprimé.", "perfect": "Je reste attentive aux éléments recueillis durant cet entretien pour apprécier le caractère véritablement libre de ce retrait exprimé par cette femme.\n\nJe reste factuelle sur les suites possibles si des éléments de contrainte étaient établis, cette information restant utile pour la protéger si nécessaire.\n\nJe reste attentive à ne pas acter ce retrait si le moindre doute persiste sur son caractère libre, cette prudence restant essentielle pour la protection de cette femme.\n\nJe reste disponible pour l''orienter vers des ressources d''aide si cette situation révèle une emprise ou une contrainte exercée sur elle.", "points": [{"position": 1, "label": "Apprécier le caractère véritablement libre de ce retrait exprimé", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : appréciation basée sur les éléments recueillis.", "groups": [{"position": 1, "keywords": ["caractère libre apprécié", "retrait examiné", "éléments recueillis"]}]}, {"position": 2, "label": "Rester factuelle sur les suites possibles si une contrainte est établie", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Information utile pour la protéger si nécessaire.", "groups": [{"position": 1, "keywords": ["contrainte établie", "protection envisagée", "suites expliquées"]}]}, {"position": 3, "label": "Ne pas acter ce retrait si le moindre doute persiste", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Prudence essentielle pour la protection de cette femme.", "groups": [{"position": 1, "keywords": ["retrait non acté", "doute persistant", "protection assurée"]}]}, {"position": 4, "label": "Rester disponible pour l''orienter vers des ressources d''aide", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Orientation en cas d''emprise ou de contrainte révélée.", "groups": [{"position": 1, "keywords": ["ressources d''aide", "emprise révélée", "orientation proposée"]}]}]}]}'::jsonb);